"use client";

import { useEffect, useMemo, useState } from "react";

import ImageUploadField from "@/components/ImageUploadField/page";
import { useUser } from "@/context/UserContext";
import { graphqlRequest } from "@/lib/graphql";
import type { UploadedMedia } from "@/lib/upload";
import styles from "./manage.module.css";

type Manga = { id: string; title: string; aliases: string[]; description: string; mangaka: string; genders: string[]; mangaCover?: string | null };
type Group = { id: string; name: string; description: string; country: string; countryCode: string; countryFlag: string; groupImage?: string | null; mangas: Manga[] };
type Country = { code: string; name: string; flag: string };
type Me = { id: string; groups: Group[] };
type Area = "group" | "manga";

const GROUP_FIELDS = "id name description country countryCode countryFlag groupImage mangas { id title aliases description mangaka genders mangaCover }";

export default function ManagePage() {
  const { authToken, authenticatedUser, authLoading } = useUser();
  const [area, setArea] = useState<Area>("group");
  const [groups, setGroups] = useState<Group[]>([]);
  const [countries, setCountries] = useState<Country[]>([]);
  const [groupID, setGroupID] = useState("new");
  const [groupForm, setGroupForm] = useState({ name: "", description: "", countryCode: "" });
  const [groupImage, setGroupImage] = useState<UploadedMedia | null>(null);
  const [title, setTitle] = useState("");
  const [matches, setMatches] = useState<Manga[]>([]);
  const [searching, setSearching] = useState(false);
  const [editingMangaID, setEditingMangaID] = useState<string | null>(null);
  const [mangaForm, setMangaForm] = useState({ description: "", mangaka: "", genders: "", aliases: "" });
  const [mangaCover, setMangaCover] = useState<UploadedMedia | null>(null);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState("");
  const selectedGroup = groups.find((group) => group.id === groupID);
  const editingManga = selectedGroup?.mangas.find((manga) => manga.id === editingMangaID);

  async function loadGroups(preferredID?: string) {
    if (!authToken) return;
    const { me, countries: availableCountries } = await graphqlRequest<{ me: Me; countries: Country[] }>(`query { me { id groups { ${GROUP_FIELDS} } } countries { code name flag } }`, {}, authToken);
    setGroups(me.groups);
    setCountries(availableCountries);
    if (preferredID) setGroupID(preferredID);
    else if (groupID === "new" && me.groups.length) setGroupID(me.groups[0].id);
  }

  useEffect(() => {
    if (authToken) void loadGroups().catch((error: Error) => setMessage(error.message));
    // loadGroups intentionally reacts only to the authenticated session.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [authToken]);

  useEffect(() => {
    const query = title.trim();
    if (query.length < 2 || !authToken) return;
    const timer = window.setTimeout(async () => {
      setSearching(true);
      try {
        const { searchMangas } = await graphqlRequest<{ searchMangas: Manga[] }>(
          `query($query:String!){searchMangas(query:$query){id title aliases description mangaka genders mangaCover}}`,
          { query },
          authToken,
        );
        setMatches(searchMangas);
      } catch (error) {
        setMessage(error instanceof Error ? error.message : "Falha na busca.");
      } finally {
        setSearching(false);
      }
    }, 350);
    return () => window.clearTimeout(timer);
  }, [title, authToken]);

  useEffect(() => {
    if (selectedGroup) {
      setGroupForm({ name: selectedGroup.name, description: selectedGroup.description, countryCode: selectedGroup.countryCode });
    } else {
      setGroupForm({ name: "", description: "", countryCode: "" });
    }
    setGroupImage(null);
    setEditingMangaID(null);
  }, [groupID]); // eslint-disable-line react-hooks/exhaustive-deps

  const exactMatch = useMemo(
    () => matches.some((manga) => manga.title.trim().localeCompare(title.trim(), undefined, { sensitivity: "base" }) === 0),
    [matches, title],
  );

  async function saveGroup(event: React.FormEvent) {
    event.preventDefault();
    if (!authToken) return;
    setBusy(true);
    setMessage("");
    try {
      const data = { ...groupForm, ...(groupImage ? { groupImageID: groupImage.id } : {}) };
      const operation = groupID === "new"
        ? `mutation($data:CreateGroupInput!){createGroup(data:$data){${GROUP_FIELDS}}}`
        : `mutation($id:ID!,$data:UpdateGroupInput!){updateGroup(id:$id,data:$data){${GROUP_FIELDS}}}`;
      const result = await graphqlRequest<{ createGroup?: Group; updateGroup?: Group }>(operation, { id: groupID, data }, authToken);
      const saved = result.createGroup ?? result.updateGroup;
      if (saved) await loadGroups(saved.id);
      setGroupImage(null);
      setMessage(groupID === "new" ? "Grupo criado." : "Grupo atualizado.");
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Falha ao salvar o grupo.");
    } finally {
      setBusy(false);
    }
  }

  async function addExisting(mangaID: string) {
    if (!authToken || !selectedGroup) return;
    setBusy(true);
    try {
      await graphqlRequest(
        "mutation($mangaID:ID!,$groupID:ID!){addMangaToGroup(mangaID:$mangaID,groupID:$groupID){id}}",
        { mangaID, groupID: selectedGroup.id },
        authToken,
      );
      await loadGroups(selectedGroup.id);
      setMessage("Mangá relacionado ao grupo sem criar uma cópia.");
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Falha ao relacionar o mangá.");
    } finally {
      setBusy(false);
    }
  }

  function editManga(manga: Manga) {
    setEditingMangaID(manga.id);
    setTitle(manga.title);
    setMangaForm({ description: manga.description, mangaka: manga.mangaka, genders: manga.genders.join(", "), aliases: manga.aliases.join(", ") });
    setMangaCover(null);
  }

  async function saveManga(event: React.FormEvent) {
    event.preventDefault();
    if (!authToken || !selectedGroup) return;
    setBusy(true);
    setMessage("");
    const data = {
      title: title.trim(),
      description: mangaForm.description,
      mangaka: mangaForm.mangaka,
      genders: mangaForm.genders.split(",").map((value) => value.trim()).filter(Boolean),
      aliases: mangaForm.aliases.split(",").map((value) => value.trim()).filter(Boolean),
      ...(mangaCover ? { mangaCoverID: mangaCover.id } : {}),
    };
    try {
      if (editingMangaID) {
        await graphqlRequest(
          "mutation($id:ID!,$data:UpdateMangaInput!){updateManga(id:$id,data:$data){id title}}",
          { id: editingMangaID, data },
          authToken,
        );
        setMessage("Metadados do mangá atualizados.");
      } else {
        await graphqlRequest(
          "mutation($groupID:ID!,$data:CreateMangaInput!){createManga(groupID:$groupID,data:$data){id title}}",
          { groupID: selectedGroup.id, data },
          authToken,
        );
        setMessage("Mangá criado no catálogo global e relacionado ao grupo.");
      }
      await loadGroups(selectedGroup.id);
      setEditingMangaID(null);
      setMangaCover(null);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Falha ao salvar o mangá.");
    } finally {
      setBusy(false);
    }
  }

  if (authLoading) return <main className={styles.page}>Carregando…</main>;
  if (!authenticatedUser) return <main className={styles.page}>Entre na sua conta para acessar a área de gestão.</main>;

  return (
    <main className={styles.page}>
      <header className={styles.heading}><div><h1>Área de gestão</h1><p>Administre grupos e o catálogo sem alterar o fluxo de publicação dos capítulos.</p></div></header>
      <div className={styles.layout}>
        <nav className={styles.side} aria-label="Áreas administrativas">
          <button className={area === "group" ? styles.active : ""} onClick={() => setArea("group")}>Grupo</button>
          <button className={area === "manga" ? styles.active : ""} onClick={() => setArea("manga")}>Mangás</button>
        </nav>
        <section className={styles.content}>
          {area === "group" ? (
            <form className={styles.form} onSubmit={saveGroup}>
              <div className={styles.sectionTitle}><div><h2>{selectedGroup ? "Dados do grupo" : "Criar grupo"}</h2><p>Informações públicas da sua scan.</p></div><select value={groupID} onChange={(event) => setGroupID(event.target.value)}><option value="new">Novo grupo</option>{groups.map((group) => <option value={group.id} key={group.id}>{group.name}</option>)}</select></div>
              <ImageUploadField label="Imagem do grupo" purpose="GROUP_IMAGE" shape="square" currentUrl={selectedGroup?.groupImage} value={groupImage} onChange={setGroupImage} disabled={busy} />
              <label>Nome<input required maxLength={120} value={groupForm.name} onChange={(event) => setGroupForm({ ...groupForm, name: event.target.value })} /></label>
              <label>Descrição<textarea required maxLength={1200} value={groupForm.description} onChange={(event) => setGroupForm({ ...groupForm, description: event.target.value })} /></label>
              <label>País<select required value={groupForm.countryCode} onChange={(event) => setGroupForm({ ...groupForm, countryCode: event.target.value })}><option value="" disabled>Selecione um país</option>{countries.map((country) => <option key={country.code} value={country.code}>{country.flag} {country.name}</option>)}</select></label>
              <button className={styles.primary} disabled={busy}>{busy ? "Salvando…" : selectedGroup ? "Salvar grupo" : "Criar grupo"}</button>
            </form>
          ) : (
            <div className={styles.mangaArea}>
              <div className={styles.sectionTitle}><div><h2>Catálogo global</h2><p>Pesquise antes de cadastrar. O grupo apenas se relaciona à obra.</p></div><select value={groupID === "new" ? "" : groupID} onChange={(event) => setGroupID(event.target.value)}><option value="" disabled>Selecione o grupo</option>{groups.map((group) => <option value={group.id} key={group.id}>{group.name}</option>)}</select></div>
              {!selectedGroup ? <p className={styles.empty}>Crie ou selecione um grupo para continuar.</p> : <>
                <label className={styles.search}>Título<input value={title} onChange={(event) => { setTitle(event.target.value); setEditingMangaID(null); }} placeholder="Digite ao menos dois caracteres" /></label>
                <div className={styles.status}>{searching ? "Pesquisando…" : exactMatch ? "Este título já está no catálogo." : title.trim().length >= 2 ? "Nenhum título idêntico. Confira os semelhantes abaixo." : ""}</div>
                {matches.length > 0 && <div className={styles.results}>{matches.map((manga) => <div key={manga.id}><span><strong>{manga.title}</strong><small>{manga.mangaka}</small></span><button disabled={busy} onClick={() => void addExisting(manga.id)}>Usar existente</button></div>)}</div>}
                <form className={styles.form} onSubmit={saveManga}>
                  <h3>{editingManga ? `Editando ${editingManga.title}` : "Novo mangá"}</h3>
                  <ImageUploadField label="Capa" purpose="MANGA_COVER" shape="cover" currentUrl={editingManga?.mangaCover} value={mangaCover} onChange={setMangaCover} disabled={busy} />
                  <label>Descrição<textarea required minLength={120} maxLength={600} value={mangaForm.description} onChange={(event) => setMangaForm({ ...mangaForm, description: event.target.value })} /></label>
                  <label>Mangaká<input required value={mangaForm.mangaka} onChange={(event) => setMangaForm({ ...mangaForm, mangaka: event.target.value })} /></label>
                  <label>Gêneros (separados por vírgula)<input required value={mangaForm.genders} onChange={(event) => setMangaForm({ ...mangaForm, genders: event.target.value })} /></label>
                  <label>Títulos alternativos (separados por vírgula)<input value={mangaForm.aliases} onChange={(event) => setMangaForm({ ...mangaForm, aliases: event.target.value })} /></label>
                  <div className={styles.actions}><button className={styles.primary} disabled={busy || (!editingMangaID && exactMatch)}>{busy ? "Salvando…" : editingMangaID ? "Salvar mangá" : "Cadastrar no catálogo"}</button>{editingMangaID && <button type="button" onClick={() => setEditingMangaID(null)}>Cancelar edição</button>}</div>
                </form>
                <div className={styles.list}><h3>Mangás relacionados ao grupo</h3>{selectedGroup.mangas.length ? selectedGroup.mangas.map((manga) => <div key={manga.id}><span>{manga.title}</span><button onClick={() => editManga(manga)}>Editar metadados</button></div>) : <p className={styles.empty}>Nenhum mangá relacionado.</p>}</div>
              </>}
            </div>
          )}
          {message && <p className={styles.message} role="status">{message}</p>}
        </section>
      </div>
    </main>
  );
}
